-- 519_batch3_curated.sql — #519 shape (a), batch 3: 39 curated rows for hidden storyless OSM pins
-- Metros: San Francisco, Los Angeles, San Diego, Seattle, Portland.
-- Each row: the hidden pin's EXACT name and stored coordinate (places:v34 rows, read 2026-10-22); one sentence in our own
-- words; the Wikipedia article as source_url. Candidates came from the all-metro scan (loose name match to a Wikipedia
-- article, same-article twins and wrong-type matches dropped, pins the live map already serves dropped), then each was
-- hand-judged. Every name was checked for same-name pins within 2 km (CURATED_MATCH_M): rows whose story already serves
-- through a same-name Wikipedia or storied OSM pin were cut, so no row overrides an existing story.
--
-- RUN: the SQL editor, this whole file in its own tab. Re-runnable: a row is skipped when a same-name curated row
-- already sits within 50 m. Expect 39 rows returned on the first run, 0 on a re-run.
-- THEN (new tab): select name, category, dist_m from public.curated_category_backfill(true) order by 1;
--   expect 39 rows, every dist_m 0.
-- BACK-OUT, per metro: delete from public.curated_descriptions where note = '#519 rescue line — <metro> (2026-10-22)';

with v(name, lat, lng, description, source_url, note) as (values
  ($t$Angel Island Immigration Station$t$, 37.8691241::double precision, -122.426195::double precision, $t$From 1910 to 1940 immigrants arriving in San Francisco were held and questioned here, including some 100,000 Chinese and 85,000 Japanese newcomers.$t$, $t$https://en.wikipedia.org/wiki/Angel_Island_Immigration_Station$t$, $t$#519 rescue line — San Francisco (2026-10-22)$t$),
  ($t$Battery Howe-Wagner$t$, 37.8024898::double precision, -122.47218::double precision, $t$This gun battery, active from 1895 to 1920, was one of seventeen built at Fort Winfield Scott to guard San Francisco and the Golden Gate.$t$, $t$https://en.wikipedia.org/wiki/Battery_Howe-Wagner$t$, $t$#519 rescue line — San Francisco (2026-10-22)$t$),
  ($t$Blake Garden$t$, 37.9139157::double precision, -122.2847132::double precision, $t$Landscape architect Mabel Symmes designed this garden for the estate of her sister and brother-in-law, Anita and Anson Blake; it is now a teaching garden for UC Berkeley.$t$, $t$https://en.wikipedia.org/wiki/Blake_Garden_(Kensington,_California)$t$, $t$#519 rescue line — San Francisco (2026-10-22)$t$),
  ($t$Maritime Plaza$t$, 37.7955872::double precision, -122.3996226::double precision, $t$Designed in 1967 by Sasaki, Walker and Associates, this two-acre park is a roof garden raised above the street around One Maritime Plaza.$t$, $t$https://en.wikipedia.org/wiki/Maritime_Plaza$t$, $t$#519 rescue line — San Francisco (2026-10-22)$t$),
  ($t$Railroad Ferry Museum$t$, 37.8725417::double precision, -122.4521626::double precision, $t$The museum fills the 1886 San Francisco and North Pacific Railroad depot, a Greek Revival building made to be moved; it once stood on a wharf before it reached this spot.$t$, $t$https://en.wikipedia.org/wiki/Tiburon_Railroad_%26_Ferry_Depot_Museum$t$, $t$#519 rescue line — San Francisco (2026-10-22)$t$),
  ($t$Ulrich Field$t$, 37.7769444::double precision, -122.4477778::double precision, $t$Built in 1953, the University of San Francisco's baseball field is named for Max Ulrich, a San Franciscan who gave money toward it.$t$, $t$https://en.wikipedia.org/wiki/Dante_Benedetti_Diamond_at_Max_Ulrich_Field$t$, $t$#519 rescue line — San Francisco (2026-10-22)$t$),
  ($t$United States Mint$t$, 37.7701013::double precision, -122.4275118::double precision, $t$San Francisco's branch of the U.S. Mint opened in 1854 to serve the Gold Rush; this third building took over the work in 1937.$t$, $t$https://en.wikipedia.org/wiki/San_Francisco_Mint$t$, $t$#519 rescue line — San Francisco (2026-10-22)$t$),
  ($t$West Berkeley Shellmound$t$, 37.8685198::double precision, -122.30048::double precision, $t$An Ohlone village on Strawberry Creek stood here, the earliest known human settlement in the Bay Area; its shellmound held burials, shells and ceremonial objects.$t$, $t$https://en.wikipedia.org/wiki/West_Berkeley_Shellmound$t$, $t$#519 rescue line — San Francisco (2026-10-22)$t$),
  ($t$América Tropical Interpretative Center$t$, 34.0576322::double precision, -118.2381617::double precision, $t$David Alfaro Siqueiros painted his 98-foot América Tropical mural on the Italian Hall in 1932; it was whitewashed almost at once and only restored for view in 2012.$t$, $t$https://en.wikipedia.org/wiki/Am%C3%A9rica_Tropical%3A_Oprimida_y_Destrozada_por_los_Imperialismos$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Antonio Aguilar$t$, 34.056721::double precision, -118.2377424::double precision, $t$This equestrian statue honors Mexican singer and actor Antonio Aguilar, at the Placita de Dolores across from Union Station.$t$, $t$https://en.wikipedia.org/wiki/Equestrian_statue_of_Antonio_Aguilar$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Cahuenga Branch Los Angeles Public Library$t$, 34.0911463::double precision, -118.2889527::double precision, $t$Built in 1916 with a grant from Andrew Carnegie, this is the third-oldest branch of the Los Angeles Public Library and one of three Carnegie libraries left in the city.$t$, $t$https://en.wikipedia.org/wiki/Cahuenga_Branch_Library$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$El Paseo Cahuenga Park$t$, 34.1307164::double precision, -118.3498072::double precision, $t$In 1831 the Battle of Cahuenga Pass pitted Mexican Governor Manuel Victoria against local landowners; only two men died, and Victoria was badly wounded.$t$, $t$https://en.wikipedia.org/wiki/Battle_of_Cahuenga_Pass$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Fire Station No. 30, Engine Company No. 30$t$, 34.0284633::double precision, -118.2472529::double precision, $t$Built in 1913, this firehouse was segregated in 1924, and only Black firefighters served here until 1956.$t$, $t$https://en.wikipedia.org/wiki/Fire_Station_No._30,_Engine_Company_No._30$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Gen. Douglas MacArthur$t$, 34.0573638::double precision, -118.277607::double precision, $t$Roger Noble Burnham's statue of MacArthur stands beside a decorative pool shaped like the western Pacific Ocean.$t$, $t$https://en.wikipedia.org/wiki/MacArthur_Monument_(Los_Angeles)$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Hale House$t$, 34.0882311::double precision, -118.2079465::double precision, $t$This 1887 Queen Anne mansion has been called the most photographed house in Los Angeles; it was moved here to Heritage Square in 1970.$t$, $t$https://en.wikipedia.org/wiki/Hale_House_(Los_Angeles,_California)$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Hecuba, Queen of Troy$t$, 34.025089::double precision, -118.2847258::double precision, $t$USC's statue of the queen of Troy was made as a female counterpart to the university's famous Tommy Trojan.$t$, $t$https://en.wikipedia.org/wiki/Hecuba_(statue)$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Highland Camrose Park$t$, 34.1090858::double precision, -118.3370025::double precision, $t$This park holds the Highland-Camrose Bungalow Village, Craftsman cottages built as homes and later used as offices by groups tied to the nearby Hollywood Bowl.$t$, $t$https://en.wikipedia.org/wiki/Highland-Camrose_Bungalow_Village$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Italian American Museum of Los Angeles$t$, 34.0580596::double precision, -118.237764::double precision, $t$Opened in 2016 in the historic Italian Hall, this is the first museum in Southern California devoted to Italian Americans.$t$, $t$https://en.wikipedia.org/wiki/Italian_American_Museum_of_Los_Angeles$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Martyrs Memorial and Museum of the Holocaust$t$, 34.0641767::double precision, -118.3697998::double precision, $t$Founded in 1961 by Holocaust survivors, this is the oldest Holocaust museum in the United States.$t$, $t$https://en.wikipedia.org/wiki/Holocaust_Museum_LA$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Savannah Memorial Park$t$, 34.0818713::double precision, -118.067414::double precision, $t$In use since 1850, with some burials perhaps older, this is the oldest American non-sectarian cemetery in Southern California.$t$, $t$https://en.wikipedia.org/wiki/Savannah_Memorial_Park$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Vista Hermosa Park$t$, 34.0616986::double precision, -118.2568995::double precision, $t$This 10.5-acre park was built on a former oil field; the polluted soil was replaced and a vent system installed to control gas from the ground.$t$, $t$https://en.wikipedia.org/wiki/Vista_Hermosa_Natural_Park$t$, $t$#519 rescue line — Los Angeles (2026-10-22)$t$),
  ($t$Bennington Monument$t$, 32.6899207::double precision, -117.2444382::double precision, $t$This 60-foot granite obelisk honors the 66 men killed when the boiler of the gunboat USS Bennington exploded in San Diego Bay on July 21, 1905.$t$, $t$https://en.wikipedia.org/wiki/USS_Bennington_Monument$t$, $t$#519 rescue line — San Diego (2026-10-22)$t$),
  ($t$MCRD San Diego Command Museum$t$, 32.7427301::double precision, -117.1945373::double precision, $t$Opened on November 10, 1987, in Day Hall at the Marine Corps Recruit Depot, this museum shows the history of the Marine Corps.$t$, $t$https://en.wikipedia.org/wiki/MCRD_San_Diego_Command_Museum$t$, $t$#519 rescue line — San Diego (2026-10-22)$t$),
  ($t$Martin Luther King Jr Promenade$t$, 32.7062516::double precision, -117.1582417::double precision, $t$Dedicated in 1992, this 12-acre linear park doubles as a memorial walk to Martin Luther King Jr.$t$, $t$https://en.wikipedia.org/wiki/Martin_Luther_King_Jr._Promenade$t$, $t$#519 rescue line — San Diego (2026-10-22)$t$),
  ($t$PSA Flight 182$t$, 32.743771::double precision, -117.120351::double precision, $t$On September 25, 1978, a PSA Boeing 727 and a small Cessna collided over San Diego, the deadliest air disaster in California history.$t$, $t$https://en.wikipedia.org/wiki/Pacific_Southwest_Airlines_Flight_182$t$, $t$#519 rescue line — San Diego (2026-10-22)$t$),
  ($t$San Diego Police Museum$t$, 32.7106897::double precision, -117.1705108::double precision, $t$Built in 1939, the Old Police Headquarters served the San Diego Police Department until 1987.$t$, $t$https://en.wikipedia.org/wiki/Old_Police_Headquarters$t$, $t$#519 rescue line — San Diego (2026-10-22)$t$),
  ($t$Santa Fe Depot$t$, 32.7169982::double precision, -117.1695567::double precision, $t$The Santa Fe Railway built this twin-domed Spanish Colonial Revival station to replace a small 1887 Victorian depot; it is on the National Register.$t$, $t$https://en.wikipedia.org/wiki/Santa_Fe_Depot_(San_Diego)$t$, $t$#519 rescue line — San Diego (2026-10-22)$t$),
  ($t$East Queen Anne Playfield$t$, 47.6361385::double precision, -122.353801::double precision, $t$Known locally as Little Howe, this small park was created in 1910 on land the city bought from John and Ida Watrons.$t$, $t$https://en.wikipedia.org/wiki/East_Queen_Anne_Playground$t$, $t$#519 rescue line — Seattle (2026-10-22)$t$),
  ($t$Historic Ballard Fire Station No. 18$t$, 47.6682992::double precision, -122.3830819::double precision, $t$This National Register firehouse once served Ballard; since 2024 it has been a Latin American restaurant and nightclub.$t$, $t$https://en.wikipedia.org/wiki/Fire_Station_No._18_(Seattle)$t$, $t$#519 rescue line — Seattle (2026-10-22)$t$),
  ($t$Martin Luther King Junior Civil Rights Memorial Park$t$, 47.5824243::double precision, -122.297246::double precision, $t$Robert Kelly's 30-foot sculpture here was inspired by King's "I've Been to the Mountaintop" speech and given to the city in 1991.$t$, $t$https://en.wikipedia.org/wiki/Martin_Luther_King_Jr._Civil_Rights_Memorial_Park$t$, $t$#519 rescue line — Seattle (2026-10-22)$t$),
  ($t$Capt. George Vancouver Monument Plaza$t$, 45.6217675::double precision, -122.6737883::double precision, $t$Jay Rood's 1992 sculpture Boat of Discovery marks the bicentennial of the 1792 exploration and naming of the Columbia River.$t$, $t$https://en.wikipedia.org/wiki/Captain_George_Vancouver_Monument_Plaza$t$, $t$#519 rescue line — Portland (2026-10-22)$t$),
  ($t$Captain George Vancouver - Royal Navy$t$, 45.6258925::double precision, -122.6763139::double precision, $t$Jim Demetro's 9-foot bronze of the explorer, about 1,500 pounds and paid for by private donors, went up here in 2000.$t$, $t$https://en.wikipedia.org/wiki/Statue_of_George_Vancouver_(Vancouver,_Washington)$t$, $t$#519 rescue line — Portland (2026-10-22)$t$),
  ($t$Dr. John McLoughlin Memorial Bridge$t$, 45.3741568::double precision, -122.6015076::double precision, $t$Conde McCullough's tied-arch bridge carries McLoughlin Boulevard across the Clackamas River between Oregon City and Gladstone.$t$, $t$https://en.wikipedia.org/wiki/John_McLoughlin_Bridge$t$, $t$#519 rescue line — Portland (2026-10-22)$t$),
  ($t$Hawthorne Bridge$t$, 45.5140431::double precision, -122.6736533::double precision, $t$The oldest working vertical-lift bridge in the United States and the oldest highway bridge in Portland, it also carries more bikes than any other bridge in Oregon.$t$, $t$https://en.wikipedia.org/wiki/Hawthorne_Bridge$t$, $t$#519 rescue line — Portland (2026-10-22)$t$),
  ($t$Interstate Bridge$t$, 45.6209544::double precision, -122.6738123::double precision, $t$The northbound span of this pair of lift bridges opened in 1917 to carry traffic over the Columbia between Portland and Vancouver.$t$, $t$https://en.wikipedia.org/wiki/Interstate_Bridge$t$, $t$#519 rescue line — Portland (2026-10-22)$t$),
  ($t$Ladd Circle$t$, 45.5085439::double precision, -122.6494189::double precision, $t$This circle is the hub of Ladd's Addition, Portland's oldest planned neighborhood, whose diagonal streets break from the grid around it.$t$, $t$https://en.wikipedia.org/wiki/Ladd's_Addition$t$, $t$#519 rescue line — Portland (2026-10-22)$t$),
  ($t$Old Apple Tree Park$t$, 45.6219864::double precision, -122.6705041::double precision, $t$This park was home to the Old Apple Tree, said to be the oldest apple tree in the Pacific Northwest; tests showed its apples were genetically unique.$t$, $t$https://en.wikipedia.org/wiki/Old_Apple_Tree_Park$t$, $t$#519 rescue line — Portland (2026-10-22)$t$),
  ($t$Portland Union Station$t$, 45.5290132::double precision, -122.6767667::double precision, $t$This Old Town station is one of the two western ends of Amtrak's Empire Builder, alongside Seattle's King Street Station.$t$, $t$https://en.wikipedia.org/wiki/Portland_Union_Station$t$, $t$#519 rescue line — Portland (2026-10-22)$t$),
  ($t$Spring Park Natural Area$t$, 45.4339091::double precision, -122.6455359::double precision, $t$After two decades of planning, this park opened in 2015 and gives access to Elk Rock Island in the Willamette.$t$, $t$https://en.wikipedia.org/wiki/Spring_Park_(Milwaukie,_Oregon)$t$, $t$#519 rescue line — Portland (2026-10-22)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
